"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[801],{67502(a,n,i){i.r(n),i.d(n,{assets:()=>o,contentTitle:()=>r,default:()=>l,frontMatter:()=>s,metadata:()=>t,toc:()=>m});const t=JSON.parse('{"id":"guides/intro-to-patterns","title":"Development workflow","description":"Ang Qiskit pattern ay ang hanay ng malalawak na hakbang na ginagamit sa pagpapatakbo ng domain-specific na problema sa quantum hardware.","source":"@site/i18n/tl/docusaurus-plugin-content-docs/current/guides/intro-to-patterns.mdx","sourceDirName":"guides","slug":"/guides/intro-to-patterns","permalink":"/guides/intro-to-patterns","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/guides/intro-to-patterns.mdx","tags":[],"version":"current","frontMatter":{"title":"Development workflow","description":"Ang Qiskit pattern ay ang hanay ng malalawak na hakbang na ginagamit sa pagpapatakbo ng domain-specific na problema sa quantum hardware."},"sidebar":"tutorialsSidebar","previous":{"title":"Mga Madalas na Tanong (FAQ)","permalink":"/guides/faq"},"next":{"title":"Gabay sa migration ng Qiskit v2.0","permalink":"/guides/qiskit-2.0"}}');var g=i(74848),e=i(28453);const s={title:"Development workflow",description:"Ang Qiskit pattern ay ang hanay ng malalawak na hakbang na ginagamit sa pagpapatakbo ng domain-specific na problema sa quantum hardware."},r="Development workflow",o={},m=[{value:"I-map ang problema sa mga quantum circuit at operator",id:"map-the-problem-to-quantum-circuits-and-operators",level:2},{value:"I-optimize para sa target na hardware",id:"optimize-for-target-hardware",level:2},{value:"I-execute sa target na hardware",id:"execute-on-target-hardware",level:2},{value:"Post-process ang mga resulta",id:"post-process-results",level:2}];function u(a){const n={em:"em",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,e.R)(),...a.components};return(0,g.jsxs)(g.Fragment,{children:["\n",(0,g.jsx)(n.header,{children:(0,g.jsx)(n.h1,{id:"development-workflow",children:"Development workflow"})}),"\n",(0,g.jsxs)(n.p,{children:["Ang terminong ",(0,g.jsx)(n.em,{children:"Qiskit pattern"})," ay naglalarawan ng development workflow para sa pagba-break down ng mga domain-specific na problema at pag-contextualize ng mga kinakailangang kakayahan sa iba't ibang yugto. Nagbibigay ito ng maayos na composability ng mga bagong kakayahang binuo ng mga mananaliksik ng IBM Quantum\xae (at ng iba pa), at nagbubukas ng hinaharap kung saan ang mga quantum computing task ay isasagawa ng makapangyarihang heterogenous (CPU/GPU/QPU) na computing infrastructure. Ang mga block o grupo ng mga block ang gumaganap ng mga hakbang ng isang pattern, na ang Qiskit SDK ang nagbibigay ng mahalagang pundasyon, sinusuportahan ng ibang mga tool o serbisyong binuo ng IBM Quantum o ng quantum open-source na komunidad. Ang mga Qiskit pattern ay nagbibigay-daan sa mga domain expert na tukuyin ang isang problema at i-compose ang mga tooling (block) na nagtatamo ng isang Qiskit pattern. Ang pattern na iyon ay maaaring i-execute nang lokal, sa pamamagitan ng cloud services, o i-deploy gamit ang Qiskit Serverless."]}),"\n",(0,g.jsx)(n.p,{children:"Ang apat na hakbang ng isang Qiskit pattern ay ang mga sumusunod:"}),"\n",(0,g.jsxs)(n.ul,{children:["\n",(0,g.jsxs)(n.li,{children:[(0,g.jsx)(n.strong,{children:"I-map"})," ang problema sa mga quantum circuit at operator"]}),"\n",(0,g.jsxs)(n.li,{children:[(0,g.jsx)(n.strong,{children:"I-optimize"})," para sa target na hardware"]}),"\n",(0,g.jsxs)(n.li,{children:[(0,g.jsx)(n.strong,{children:"I-execute"})," sa target na hardware"]}),"\n",(0,g.jsxs)(n.li,{children:[(0,g.jsx)(n.strong,{children:"Post-process"})," ang mga resulta"]}),"\n"]}),"\n",(0,g.jsx)(n.p,{children:"Ang bawat hakbang ay detalyadong tinalakay sa mga seksyon sa ibaba."}),"\n",(0,g.jsx)(n.h2,{id:"map-the-problem-to-quantum-circuits-and-operators",children:"I-map ang problema sa mga quantum circuit at operator"}),"\n",(0,g.jsx)(n.p,{children:"Inilalarawan ng hakbang na ito kung paano nagsisimula ang isang user sa isang klasikal na problema at nag-iisip kung paano ito imi-map sa isang quantum computer. Halimbawa, sa mga aplikasyon tulad ng chemistry at quantum simulation, ang hakbang na ito ay karaniwang kinabibilangan ng pagbuo ng quantum circuit na kumakatawan sa Hamiltonian na sinusubukan mong resolbahin. Sa hakbang na ito, para sa ilang partikular na problema, maaari ring maging kapaki-pakinabang na tukuyin nang maaga ang pagma-map ng problema sa mga qubit sa heavy-hex (o gross) na lattice ng IBM\xae hardware, kung ang istruktura ng problema ay angkop sa mas maagang pag-optimize. Kapaki-pakinabang din na isaalang-alang sa puntong ito ang magiging resulta ng partikular na algorithm bilang paghahanda para sa mas huling execute na hakbang \u2014 halimbawa, kung ang nais na resulta ay kinabibilangan ng pag-infer ng mga correlation function gamit ang Hadamard tests, maaari kang maghanda na gumamit ng Sampler, samantalang ang pagtukoy ng mga observable ay gagamit ng Estimator at maaaring magbigay ng maraming opsyon sa error mitigation."}),"\n",(0,g.jsx)(n.p,{children:"Ang output ng hakbang na ito ay karaniwang isang koleksyon ng mga circuit o quantum operator na maaaring i-optimize para sa hardware sa susunod na hakbang."}),"\n",(0,g.jsx)(n.h2,{id:"optimize-for-target-hardware",children:"I-optimize para sa target na hardware"}),"\n",(0,g.jsx)(n.p,{children:"Sa hakbang na ito, kukuhanin mo ang mga abstract na circuit (o operator) na ginawa mula sa map na hakbang at magsasagawa ng serye ng mga optimization sa mga ito. Maaaring kasama dito ang pagma-map ng ruta at layout ng circuit sa pisikal na qubit hardware, pag-convert sa basis gates ng hardware, at pagbabawas ng bilang ng mga operasyon \u2014 lahat ay dinisenyo upang ma-optimize ang posibilidad ng tagumpay sa mas huling execute na hakbang. Sa puntong ito, maaari mo ring subukin ang iyong mga circuit gamit ang isang simulator bago i-execute sa totoong hardware sa susunod na hakbang."}),"\n",(0,g.jsx)(n.p,{children:"Sa hakbang na ito, ang mga abstract na circuit ay dapat na i-transpile sa Instruction Set Architecture (ISA) na mga circuit. Ang isang ISA circuit ay isa na binubuo lamang ng mga gate na naiintindihan ng target na hardware (basis gates), at anumang multi-qubit gate na kailangang sumunod sa mga connectivity constraint (coupling map). Tanging ang mga ISA circuit lamang ang maaaring patakbuhin sa IBM hardware gamit ang IBM Qiskit Runtime."}),"\n",(0,g.jsx)(n.h2,{id:"execute-on-target-hardware",children:"I-execute sa target na hardware"}),"\n",(0,g.jsx)(n.p,{children:"Ang hakbang na ito ay kinabibilangan ng pagpapatakbo ng iyong mga circuit sa hardware at gumagawa ng mga output ng quantum computation. Ang mga ISA circuit na ginawa sa nakaraang hakbang ay maaaring i-execute gamit ang alinman sa Sampler o Estimator primitive mula sa Qiskit Runtime, na ini-initialize nang lokal sa iyong computer o mula sa isang cluster o iba pang heterogenous na compute environment. Ang mga ito ay maaaring i-execute sa isang Batch, na nagbibigay-daan sa parallel na transpilation para sa kahusayan ng klasikal na computation \u2014 o sa isang Session, na nagbibigay-daan sa mga iterative na task na maipatupad nang mahusay nang walang mga pagkaantala sa pila. Sa hakbang na ito, mayroon ding opsyon na i-configure ang ilang partikular na teknik sa error suppression at mitigation na ibinibigay ng Qiskit Runtime."}),"\n",(0,g.jsx)(n.p,{children:"Depende sa kung gumagamit ka ng Sampler o Estimator primitive, ang kinalabasan ng hakbang na ito ay magiging iba. Kung gumagamit ng Sampler, ang output ay magiging per-shot na mga sukat sa anyo ng mga bitstring. Kung gumagamit ng Estimator, ang output ay magiging mga expectation value ng mga observable na tumutugma sa mga pisikal na dami o cost function."}),"\n",(0,g.jsx)(n.h2,{id:"post-process-results",children:"Post-process ang mga resulta"}),"\n",(0,g.jsx)(n.p,{children:"Ang huling hakbang na ito ay kinabibilangan ng pagsasama-sama ng mga output mula sa nakaraang hakbang upang makuha ang nais na resulta. Maaaring kasama dito ang iba't ibang klasikal na data-processing na hakbang tulad ng pag-visualize ng mga resulta, mga teknik sa readout error mitigation, pag-marginalize ng mga quasi-probability distribution upang matukoy ang mga resulta sa mas maliliit na grupo ng mga qubit, o post-selection batay sa likas na katangian ng problema, tulad ng kabuuang spin, parity, o particle conservation sa pamamagitan ng pag-alis ng mga hindi pisikal na observable."}),"\n",(0,g.jsx)(n.p,{children:"Habang lumalayo ang larangan mula sa bespoke na pagbuo ng circuit patungo sa mga utility-scale na workflow, ang flexibility at dali na pinapayagan ng mga Qiskit pattern sa mga user na i-compose ang iba't ibang hakbang ng pattern ay nagbubukas ng quantum computing sa malawak na iba't ibang aplikasyon at teknik para sa madaling paggamit ng mga quantum computational scientist."})]})}function l(a={}){const{wrapper:n}={...(0,e.R)(),...a.components};return n?(0,g.jsx)(n,{...a,children:(0,g.jsx)(u,{...a})}):u(a)}},28453(a,n,i){i.d(n,{R:()=>s,x:()=>r});var t=i(96540);const g={},e=t.createContext(g);function s(a){const n=t.useContext(e);return t.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(g):a.components||g:s(a.components),t.createElement(e.Provider,{value:n},a.children)}}}]);